const $=s=>document.querySelector(s), key='iwantresume-v1';
const blank=()=>({format:'ats',name:'',title:'',email:'',phone:'',location:'',website:'',summary:'',skills:'',certifications:'',photo:'',experience:[{role:'',company:'',dates:'',details:''}],education:[{degree:'',school:'',dates:''}]});
let data=blank();try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.experience)&&Array.isArray(saved.education))data={...data,...saved}}catch{}
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function persist(){try{localStorage.setItem(key,JSON.stringify(data));$('#saved').textContent='Saved on this device'}catch{$('#saved').textContent='Draft could not be saved';toast('Browser storage is full. Your current resume can still be downloaded.')}}
function entries(kind){const fields=kind==='experience'?[['role','Job title'],['company','Company'],['dates','Dates'],['details','Achievements · one bullet per line']]:[['degree','Degree or qualification'],['school','School or university'],['dates','Dates']];$('#'+kind).innerHTML=data[kind].map((item,i)=>`<div class="entry"><div class="entry-top"><span>${kind==='experience'?'EXPERIENCE':'EDUCATION'} ${i+1}</span><button class="text-button" type="button" data-remove="${kind}" data-index="${i}" aria-label="Remove ${kind} ${i+1}">Remove</button></div>${fields.map(([field,label])=>`<label>${label}${field==='details'?`<textarea rows="4" data-kind="${kind}" data-index="${i}" data-field="${field}">${esc(item[field])}</textarea>`:`<input data-kind="${kind}" data-index="${i}" data-field="${field}" value="${esc(item[field])}">`}</label>`).join('')}</div>`).join('')}
function fill(){for(const el of $('#form').querySelectorAll('[name]'))el.value=data[el.name]||'';entries('experience');entries('education');render()}
function render(){const regular=data.format==='regular';for(const button of document.querySelectorAll('[data-format]')){const chosen=button.dataset.format===data.format;button.classList.toggle('selected',chosen);button.setAttribute('aria-pressed',chosen)}$('#photo-area').hidden=!regular;$('#format-label').textContent=(regular?'REGULAR':'ATS')+' / A4';$('#format-note').textContent=regular?'A polished layout with coral accents and an optional profile photo.':'Single column, standard headings, no photo. Designed for easy parsing; results vary by ATS.';const section=(title,body)=>body?`<section><h3>${title}</h3>${body}</section>`:'';$('#resume').className='paper '+data.format;$('#resume').innerHTML=`<div class="resume-head"><div><h2>${esc(data.name)||'<span class="empty">Your name</span>'}</h2><div class="job-title">${esc(data.title)||'<span class="empty">Your professional title</span>'}</div><div class="contact">${[data.email,data.phone,data.location,data.website].filter(Boolean).map(esc).join(' · ')||'<span class="empty">Email · Phone · Location · Website</span>'}</div></div>${regular&&data.photo?`<img class="portrait" src="${data.photo}" alt="Profile photo">`:''}</div>${section('Professional summary',data.summary?`<p>${esc(data.summary)}</p>`:'')}${section('Work experience',data.experience.filter(x=>x.role||x.company||x.details).map(x=>`<div class="item"><div class="item-head"><strong>${esc(x.role)}</strong><span class="date">${esc(x.dates)}</span></div><div class="sub">${esc(x.company)}</div><p>${esc(x.details)}</p></div>`).join(''))}${section('Education',data.education.filter(x=>x.degree||x.school).map(x=>`<div class="item"><div class="item-head"><strong>${esc(x.degree)}</strong><span class="date">${esc(x.dates)}</span></div><div class="sub">${esc(x.school)}</div></div>`).join(''))}${section('Skills',data.skills?`<p>${esc(data.skills)}</p>`:'')}${section('Certifications',data.certifications?`<p>${esc(data.certifications)}</p>`:'')}${!data.summary&&!data.skills&&!data.experience.some(x=>x.role||x.company)&&!data.education.some(x=>x.degree||x.school)?'<section class="empty"><h3>Your next chapter starts here</h3><p>Fill in your details on the left.<br>Your resume will come together here, in real time.</p></section>':''}`}
$('#form').addEventListener('input',e=>{const el=e.target;if(el.name)data[el.name]=el.value;else if(el.dataset.kind)data[el.dataset.kind][+el.dataset.index][el.dataset.field]=el.value;else return;persist();render()});
$('#form').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){data[b.dataset.remove].splice(+b.dataset.index,1);entries(b.dataset.remove);persist();render()}});
for(const kind of ['experience','education'])$('#add-'+kind).onclick=()=>{data[kind].push(kind==='experience'?{role:'',company:'',dates:'',details:''}:{degree:'',school:'',dates:''});entries(kind);persist();render()};
for(const b of document.querySelectorAll('[data-format]'))b.onclick=()=>{data.format=b.dataset.format;persist();render()};
$('#photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Choose a JPG, PNG or WebP smaller than 5 MB.');e.target.value='';return}try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=canvas.height=400;const size=Math.min(bitmap.width,bitmap.height);canvas.getContext('2d').drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,400,400);data.photo=canvas.toDataURL('image/jpeg',.85);bitmap.close();persist();render()}catch{toast('This image could not be opened. Try another file.')}};
$('#remove-photo').onclick=()=>{data.photo='';$('#photo').value='';persist();render()};
$('#clear').onclick=()=>{if(confirm('Clear your saved resume and start again?')){data=blank();persist();fill()}};
$('#sample').onclick=()=>{if((data.name||data.summary)&&!confirm('Replace your draft with sample content?'))return;data={...blank(),format:data.format,name:'Alex Morgan',title:'Product Designer',email:'alex.morgan@example.com',phone:'+63 912 345 6789',location:'Manila, Philippines',website:'linkedin.com/in/alexmorgan',summary:'Product designer with 5 years of experience turning complex problems into clear, accessible digital experiences. Combines user research and thoughtful design to help teams build products people love.',experience:[{role:'Senior Product Designer',company:'Studio North',dates:'2022 – Present',details:'Led the redesign of a customer portal, improving task completion by 28%.\nBuilt a design system adopted by three product teams.\nPartnered with engineers and researchers to ship accessible features.'},{role:'Product Designer',company:'Bright Digital',dates:'2019 – 2022',details:'Designed web and mobile experiences for 12 client projects.\nConducted usability studies and translated findings into design improvements.'}],education:[{degree:'BS in Information Technology',school:'University of the Philippines',dates:'2015 – 2019'}],skills:'User research, Interaction design, Figma, Prototyping, Accessibility, Design systems',certifications:'Google UX Design Certificate — Google, 2021'};persist();fill()};
$('#download').onclick=()=>{if(!data.name.trim()){toast('Add your full name before downloading.');$('input[name="name"]').focus();return}if(!window.jspdf){toast('PDF export could not load. Please refresh and try again.');return}try{const {jsPDF}=window.jspdf;const doc=new jsPDF({unit:'mm',format:'a4'}),margin=19,width=172,regular=data.format==='regular';let y=22;const next=()=>{doc.addPage();y=22;};const line=(text,size=10,bold=false,w=width)=>{doc.setFont('helvetica',bold?'bold':'normal');doc.setFontSize(size);const lines=doc.splitTextToSize(text||'',w);for(const part of lines){if(y+size*.45>277)next();doc.text(part,margin,y);y+=size*.45+1}return lines.length};const section=title=>{if(y>255)next();y+=6;doc.setDrawColor(...(regular?[237,112,91]:[150,150,150]));line(title.toUpperCase(),11,true);doc.line(margin,y-2,191,y-2);y+=3};doc.setTextColor(37,45,51);if(regular){doc.setFillColor(237,112,91);doc.rect(0,0,210,4,'F');if(data.photo)doc.addImage(data.photo,'JPEG',167,19,24,24)}line(data.name,24,true,regular&&data.photo?140:width);if(data.title)line(data.title,12,false,regular&&data.photo?140:width);y+=2;line([data.email,data.phone,data.location,data.website].filter(Boolean).join(' | '),9,false,regular&&data.photo?140:width);if(regular&&data.photo)y=Math.max(y,47);if(data.summary){section('Professional summary');line(data.summary)}const experiences=data.experience.filter(x=>x.role||x.company||x.details);if(experiences.length){section('Work experience');for(const x of experiences){if(y>252)next();if(x.role)line(x.role,11,true);line([x.company,x.dates].filter(Boolean).join(' | '),10);if(x.details)for(const bullet of x.details.split('\n').filter(x=>x.trim()))line('• '+bullet.replace(/^[•\-]\s*/,''));y+=3}}const education=data.education.filter(x=>x.degree||x.school);if(education.length){section('Education');for(const x of education){if(y>255)next();line(x.degree,11,true);line([x.school,x.dates].filter(Boolean).join(' | '),10);y+=3}}if(data.skills){section('Skills');line(data.skills)}if(data.certifications){section('Certifications');line(data.certifications)}await doc.save(data.name.replace(/[^a-z0-9\s_-]/gi,'').trim().replace(/\s+/g,'-')+'-'+data.format+'-resume.pdf');toast('Your resume is ready. Good luck with your next move!')}catch(e){console.error(e);toast('PDF export failed. Please try again.')}};
fill();

